def ring_distance(start: int, end: int, modulus: int) -> int:
    if not (0 <= start <= 65535) or not (0 <= end <= 65535) or not (0 <= modulus <= 65535):
        return -1
    if modulus == 0 or start >= modulus or end >= modulus:
        return -1
    diff = end - start
    if diff >= 0:
        return diff
    else:
        return diff + modulus
